const String responsePayloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"HCP — Read Own Grant — response payload","type":"object","additionalProperties":false,"required":["grant","directives"],"description":"The HCP Read own grant result (HCP 5.2.6): the client\'s own grant, with the directives that apply to it. Failures use trust-task-error, not this shape.","properties":{"grant":{"\$ref":"#/\$defs/Grant","description":"The grant under which the client acts, and no other (HCP 5.2.6, 6.1.5). Where it is narrowed to particular entries, a Context Client receives their `ref`s, never their `id`s (HCP 5.2.6)."},"directives":{"type":"array","items":{"\$ref":"#/\$defs/Directive"},"description":"The directives that apply to the grant (HCP 5.2.6, 6.4); empty when none applies."}}},"Directive":{"type":"object","additionalProperties":true,"required":["directiveId","action","effect","text","setBy","createdAt"],"description":"What a client may do with context it received, or on the Context Subject\'s behalf (HCP 6.4). A directive only narrows: it never authorizes a disclosure the grant does not. Where two that apply disagree, `deny` prevails over `ask-first`, and `ask-first` over `permit` (HCP 6.4).","properties":{"directiveId":{"\$ref":"#/\$defs/Urn","description":"Stable for the life of the directive (HCP 6.4)."},"action":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^(share|sign|transact|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)\$","description":"What the directive governs: `share` (passing received context to another agent), `sign` (signing, agreeing to or committing to anything on the Context Subject\'s behalf), `transact` (spending, buying or entering a contract on their behalf), or an absolute URI naming another action (HCP 6.4, A.3). A client MUST NOT treat an action it does not recognize as a permission; it reads the directive from `text`."},"effect":{"type":"string","enum":["deny","ask-first","permit"],"description":"`deny`: the client MUST NOT take the action. `ask-first`: the client MUST obtain the Context Subject\'s confirmation each time before taking it. `permit`: the client may take it without asking (HCP 6.4). HCP\'s own values, carried verbatim."},"text":{"type":"string","minLength":1,"maxLength":4096,"description":"The directive in the Context Subject\'s words (HCP 6.4). A client presents it to a model as data, never as instructions (HCP 7.4). The maxLength is a framework bound, not an HCP requirement."},"categories":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories whose context the directive governs; absent means every category, held now or later (HCP 6.4). The maxItems is a framework bound, not an HCP requirement."},"operators":{"type":"array","minItems":1,"maxItems":256,"items":{"type":"string","minLength":1,"maxLength":2048},"description":"The Client Operators the directive applies to, each a DNS domain or an operator identifier, matched as for standing rules; absent means every operator (HCP 6.4, 6.3). The maxItems is a framework bound, not an HCP requirement."},"setBy":{"type":"string","minLength":1,"maxLength":2048,"description":"Set by the provider: `context-subject`, or the `delegationId` of the delegate who set it (HCP 6.4, 6.3)."},"createdAt":{"\$ref":"#/\$defs/Instant","description":"Set by the provider: when the directive was set (HCP 6.4)."}}},"Instant":{"type":"string","format":"date-time","description":"An RFC 3339 instant."},"Category":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^([a-z][a-z0-9_]*|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)\$","description":"An HCP context category (HCP 4.5), the primary unit of access control: either a slug from HCP\'s category registry, such as `general_preferences` or `health_context`, or a custom category written as an absolute URI under a domain its definer controls. A custom category is not portable between providers without bilateral agreement (HCP 4.5)."},"Urn":{"type":"string","pattern":"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$","description":"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers."},"Grant":{"type":"object","additionalProperties":true,"required":["grantId","subject","authorizingPrincipal","client","access","grantType","issuedAt","expiresAt","status"],"description":"A grant (HCP 6.1.5). `expiresAt` is an instant for a `temporary` grant and null for a `persistent` one (HCP 6.1.4, 6.1.5). That rule is stated here and not as a schema conditional: the registry\'s Rust generator does not support `if`/`then`/`else`, so it is not checked by the schema. An HCP Provider never discloses a grant issued to one HCP Client to any other (HCP 6.1.5).","properties":{"grantId":{"\$ref":"#/\$defs/Urn","description":"Stable for the life of the grant; the `grantId` recorded in audit events (HCP 6.1.5, 8.2)."},"subject":{"\$ref":"#/\$defs/GrantParty","description":"The Context Subject, by a pseudonym specific to the client (HCP 3.4)."},"authorizingPrincipal":{"\$ref":"#/\$defs/AuthorizingPrincipal","description":"Who authorized the grant (HCP 3.4, 6.1.5)."},"client":{"\$ref":"#/\$defs/GrantClient","description":"The HCP Client the grant was issued to (HCP 6.1.5)."},"requestingParty":{"\$ref":"#/\$defs/RequestingParty","description":"The party on whose behalf the client requested access, where there is one (HCP 3.2.7, 3.4)."},"access":{"type":"array","minItems":1,"items":{"\$ref":"#/\$defs/AccessDetail"},"description":"What the grant authorizes: one or more authorization details (HCP 6.1.5)."},"scopes":{"type":"array","items":{"type":"string","maxLength":2048,"pattern":"^hcp:[^:]+(:[^:]+)*:(read|write)\$"},"description":"Scope strings derived from `access`, in the form `hcp:{category}:{action}` (HCP 6.1.1), for display. They never grant anything `access` does not (HCP 6.1.5)."},"grantType":{"type":"string","enum":["temporary","persistent"],"description":"Temporary or persistent (HCP 6.1.4). HCP\'s own values, carried verbatim."},"issuedAt":{"\$ref":"#/\$defs/Instant","description":"When the grant was issued."},"expiresAt":{"type":["string","null"],"format":"date-time","description":"For a temporary grant, its absolute expiry, never null; for a persistent grant, null (HCP 6.1.4, 6.1.5)."},"status":{"type":"string","enum":["active","revoked","expired"],"description":"`expired` on lapse of `expiresAt`, `revoked` on revocation (HCP 6.1.5, 6.2.1). HCP\'s own values, carried verbatim."}}},"AccessDetail":{"type":"object","additionalProperties":true,"required":["type","actions","categories","purposes"],"description":"An authorization detail (HCP 6.1.5); under HCP\'s OAuth Interop Profile, an RFC 9396 authorization detail (HCP 13.3). `onwardSharing` appears only in a detail that includes `read` and all of whose categories have a default sensitivity of Low (HCP 6.1.5); not checked by the schema.","properties":{"type":{"type":"string","const":"https://hcp.example/spec/authorization/context-access","description":"The HCP authorization detail type (HCP 6.1.5)."},"actions":{"type":"array","minItems":1,"uniqueItems":true,"items":{"type":"string","enum":["read","write","provenance"]},"description":"What the detail allows. `provenance` is an action only alongside `read` (HCP 6.1.5, 7.4.1); not checked by the schema."},"categories":{"type":"array","minItems":1,"uniqueItems":true,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories the detail covers (HCP 4.5)."},"purposes":{"type":"array","minItems":1,"items":{"\$ref":"#/\$defs/Purpose"},"description":"The purposes the person approved for these categories; never empty (HCP 6.1.5.2)."},"narrowedTo":{"type":"object","additionalProperties":true,"description":"An implementation-defined narrowing below category grain, which only narrows (HCP 6.1.5.1). To a Context Client, entries it names are named by `ref`, never by `id` (HCP 5.2.6)."},"onwardSharing":{"\$ref":"#/\$defs/OnwardSharing","description":"The onward sharing the person elected for the detail (HCP 3.12, 6.1.5)."}}},"OnwardSharing":{"type":"object","additionalProperties":true,"description":"Present only where the Authorizing Principal elected onward sharing for the detail (HCP 3.12, 6.1.5).","properties":{"domains":{"type":"array","uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":253},"description":"Where present, the DNS domains of the organizations the client may share with (HCP 6.1.5)."},"notTo":{"type":"array","uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":2048},"description":"Set by the provider: each DNS domain or operator a standing rule denies any of the detail\'s categories (HCP 6.1.5, 6.3)."}}},"Purpose":{"type":"object","additionalProperties":true,"required":["code","description"],"description":"A purpose with a description the person can read (HCP 6.1.5.2).","properties":{"code":{"\$ref":"#/\$defs/PurposeCode","description":"The purpose code."},"description":{"type":"string","minLength":1,"maxLength":4096,"description":"The description shown to the person before approval (HCP 6.1.5.2, 6.1.6)."}}},"PurposeCode":{"type":"string","format":"uri","minLength":1,"maxLength":2048,"pattern":"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+\$","description":"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2)."},"RequestingParty":{"type":"object","additionalProperties":true,"required":["type","id"],"description":"The Requesting Party (HCP 3.2.7).","properties":{"type":{"type":"string","enum":["person","organization"],"description":"A person or an organization. HCP\'s own values, carried verbatim."},"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Its identifier."},"name":{"type":"string","maxLength":1024,"description":"Its name."}}},"GrantClient":{"type":"object","additionalProperties":true,"required":["id","name","operator"],"description":"The client a grant was issued to (HCP 6.1.5).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Its client identifier."},"name":{"type":"string","minLength":1,"maxLength":1024,"description":"A name the person can recognize (HCP 6.1.5)."},"operator":{"\$ref":"#/\$defs/Named","description":"The Client Operator (HCP 3.2.8)."},"legalRetention":{"\$ref":"#/\$defs/LegalRetention","description":"Present only where the client declared a legal obligation to keep what it receives (HCP 6.2.5)."},"claims":{"type":"array","uniqueItems":true,"items":{"\$ref":"#/\$defs/Uri"},"description":"The client conformance claims it declared at registration (HCP 18.1); absent where it declared none."}}},"LegalRetention":{"type":"object","additionalProperties":true,"required":["record","obligation","period"],"description":"A record the client declared at registration that the law requires it to keep of what it receives (HCP 6.2.5).","properties":{"record":{"type":"string","maxLength":4096,"description":"The record kept."},"obligation":{"type":"string","maxLength":4096,"description":"The law or rule that requires it."},"period":{"type":"string","maxLength":1024,"description":"How long it is kept."}}},"Named":{"type":"object","additionalProperties":true,"required":["id","name"],"description":"An organization, by identifier and a name a person can recognize.","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Its identifier."},"name":{"type":"string","minLength":1,"maxLength":1024,"description":"Its name. The minLength is a framework bound, not an HCP requirement."}}},"Uri":{"type":"string","format":"uri","minLength":1,"maxLength":2048,"pattern":"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+\$","description":"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3)."},"AuthorizingPrincipal":{"type":"object","additionalProperties":true,"required":["id"],"description":"The Authorizing Principal (HCP 3.4). In Core it is the Context Subject and carries the same pseudonym as `subject`; under the Delegated Authorization Profile it is the delegate (HCP 17.4).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Its identifier."},"delegation":{"type":"string","minLength":1,"maxLength":2048,"description":"The delegation under which a delegate authorized the grant; present only then (HCP 6.1.5, 17.4)."}}},"GrantParty":{"type":"object","additionalProperties":true,"required":["id"],"description":"An actor a grant binds, named by identifier (HCP 3.4).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Its identifier; for the Context Subject, a pseudonym specific to the client (HCP 3.4). The minLength is a framework bound, not an HCP requirement."}}}}}';

